func (this *Blockchaincom) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	//     {
	//     "symbol": "BTC-USD",
	//     "price_24h": 47791.86,
	//     "volume_24h": 362.88635738,
	//     "last_trade_price": 47587.75
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "symbol")
	var symbol *string = this.SafeSymbol(marketId, market, "-")
	var last *string = this.SafeString(ticker, "last_trade_price")
	var baseVolume *string = this.SafeString(ticker, "volume_24h")
	var open *string = this.SafeString(ticker, "price_24h")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     nil,
		"datetime":      nil,
		"high":          nil,
		"low":           nil,
		"bid":           nil,
		"bidVolume":     nil,
		"ask":           nil,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          open,
		"close":         nil,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   nil,
		"info":          ticker,
	}, market)
}

