func (this *Blockchaincom) ParseTransactionState(state *string) *string {
	var states map[string]any = map[string]any{
		"COMPLETED": "ok",
		"REJECTED":  "failed",
		"PENDING":   "pending",
		"FAILED":    "failed",
		"REFUNDED":  "refunded",
	}
	return this.SafeString(states, state, state)
}
func (this *Blockchaincom) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// deposit
	//
	//     {
	//         "depositId":"748e9180-be0d-4a80-e175-0156150efc95",
	//         "amount":0.009,
	//         "currency":"ETH",
	//         "address":"0xEC6B5929D454C8D9546d4221ace969E1810Fa92c",
	//         "state":"COMPLETED",
	//         "txHash":"582114562140e51a80b481c2dfebaf62b4ab9769b8ff54820bb67e34d4a3ab0c",
	//         "timestamp":1633697196241
	//     }
	//
	// withdrawal
	//
	//     {
	//         "amount":30.0,
	//         "currency":"USDT",
	//         "beneficiary":"cab00d11-6e7f-46b7-b453-2e8ef6f101fa", // blockchain specific id
	//         "withdrawalId":"99df5ef7-eab6-4033-be49-312930fbd1ea",
	//         "fee":34.005078,
	//         "state":"COMPLETED",
	//         "timestamp":1634218452549
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var typeVar *string = nil
	var id *string = nil
	var amount *float64 = this.SafeNumber(transaction, "amount")
	var timestamp *int64 = this.SafeInteger(transaction, "timestamp")
	var currencyId *string = this.SafeString(transaction, "currency")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var state *string = this.SafeString(transaction, "state")
	var depositId *string = this.SafeString(transaction, "depositId")
	var withdrawalId *string = this.SafeString(transaction, "withdrawalId")
	if depositId != nil {
		typeVar = SafeStringPtr("deposit")
		id = depositId
	} else if withdrawalId != nil {
		typeVar = SafeStringPtr("withdrawal")
		id = withdrawalId
	}
	var feeCost *float64 = func() *float64 {
		if typeVar != nil && *typeVar == "withdrawal" {
			return this.SafeNumber(transaction, "fee")
		}
		return nil
	}()
	var fee map[string]any = nil
	if feeCost != nil {
		fee = map[string]any{
			"currency": code,
			"cost":     feeCost,
		}
	}
	var address *string = this.SafeString(transaction, "address")
	var txid *string = this.SafeString(transaction, "txhash")
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"addressFrom": nil,
		"address":     address,
		"addressTo":   address,
		"tagFrom":     nil,
		"tag":         nil,
		"tagTo":       nil,
		"type":        typeVar,
		"amount":      amount,
		"currency":    code,
		"status":      this.ParseTransactionState(state),
		"updated":     nil,
		"comment":     nil,
		"internal":    nil,
		"fee":         fee,
	})
}

