func (this *Blockchaincom) fetchBalanceBody(ch chan AsyncResult[Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var accountName *string = this.SafeString(params, "account", "primary")
	var paramsOmitted map[string]any = this.OmitDict(params, "account")
	var request map[string]any = map[string]any{
		"account": accountName,
	}

	r1 := <-this.PrivateGetAccounts(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//     {
	//         "primary": [
	//             {
	//                 "currency":"ETH",
	//                 "balance":0.009,
	//                 "available":0.009,
	//                 "balance_local":30.82869,
	//                 "available_local":30.82869,
	//                 "rate":3425.41
	//             },
	//             ...
	//         ]
	//     }
	//
	var balances []any = SafeListTyped(response, accountName)
	if balances == nil {
		panic(ExchangeError(this.Id + " fetchBalance() could not find the \"" + *accountName + "\" account"))
	}
	var result map[string]any = map[string]any{
		"info": response,
	}
	for i := 0; i < len(balances); i++ {
		var entry map[string]any = SafeMapTyped(balances, i)
		var currencyId *string = this.SafeString(entry, "currency")
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["free"] = this.SafeString(entry, "available")
		account["total"] = this.SafeString(entry, "balance")
		if code != nil {
			result[*code] = account
		}
	}

	ch <- AsyncResult[Balances]{Value: BalancesFromMap(this.SafeBalance(result).(map[string]any))}
	return nil
}

